import * as ZOrder from '../../common/ZOrder';

export class DoorView extends Container implements Drawable {
  constructor(private readonly model: Door) {
    super();

    // Set consistent z-index for doors (higher than walls)
    this.zIndex = ZOrder.compute({
      x: (model.p1.x + model.p2.x) / 2,
      y: (model.p1.y + model.p2.y) / 2,
      layer: ZOrder.ZPriority.WALL,
      offset: 10 // Slightly above walls
    }

// Initialize parts based on configuration
    this.parts = this.initializeParts();

    // Set Z-index for avatar
    this.zIndex = ZOrder.compute({
      x: this.x,
      y: this.y,
      layer: ZOrder.ZPriority.AVATAR
    });

    // this.directionText.x = 50;
    // this.directionText.y = 120;

    // Apply default hair color
    const hair = this.parts.find(part => part instanceof Hair) as Hair;
    if (hair) {
      hair.tint = 0x000000;
    }

import { PARTS_CONFIG, getPartsInOrder, PartConfig } from './partsConfig';
import ClotheRegistry from './ClotheRegistry';
import * as ZOrder from '../../modules/common/ZOrder';

private initializeParts(): IAvatarPart[] {
  const parts: IAvatarPart[] = [];
  const orderedParts = getPartsInOrder();

  for (const partConfig of orderedParts) {
    try {
      const part = this.createPartFromConfig(partConfig);
      if (part) {
        parts.push(part);
      }
    } catch (error) {
      console.error(`Failed to create part ${partConfig.className}:`, error);
      if (partConfig.required) {
        throw error; // Re-throw for required parts
      }
    }
  }

  return parts;
}

private createPartFromConfig(config: PartConfig): IAvatarPart | null {
  // Handle body parts
  if (config.category === 'body') {
    switch (config.className) {
      case 'AvatarRightArm':
        return new AvatarRightArm(this._direction);
      case 'AvatarLegs':
        return new AvatarLegs(this._direction);
      case 'AvatarBody':
        return new AvatarBody(this._direction);
      case 'AvatarLeftArm':
        return new AvatarLeftArm(this._direction);
      case 'AvatarHead':
        return new AvatarHead(this._direction);
      default:
        console.warn(`Unknown body part: ${config.className}`);
        return null;
    }
  }

  // Handle clothing parts via registry
  const clothe = ClotheRegistry.create(config.category, config.id, this._direction);
  return clothe;
}

/**
 * Change a specific clothing item
 */
public changeClothing(category: string, id?: string): boolean {
  // Remove existing clothing of this category
  const existingIndex = this.parts.findIndex(part => 
    part.constructor.name.toLowerCase().includes(category.toLowerCase())
  );

  if (existingIndex !== -1) {
    const existingPart = this.parts[existingIndex];
    this.removeChild(existingPart);
    this.parts.splice(existingIndex, 1);
  }

  // Add new clothing if id provided
  if (id) {
    const newClothe = ClotheRegistry.create(category, id, this._direction);
    if (newClothe) {
      // Find the correct position to insert based on configuration
      const config = PARTS_CONFIG.find(p => p.category === category);
      const insertIndex = config ? this.findInsertionIndex(config.order) : this.parts.length;

      this.parts.splice(insertIndex, 0, newClothe);
      this.renderParts();
      return true;
    }
  }

  this.renderParts();
  return false;
}

private findInsertionIndex(targetOrder: number): number {
  for (let i = 0; i < this.parts.length; i++) {
    const partConfig = this.getPartConfig(this.parts[i]);
    if (partConfig && partConfig.order > targetOrder) {
      return i;
    }
  }
  return this.parts.length;
}

private getPartConfig(part: IAvatarPart): PartConfig | undefined {
  const className = part.constructor.name;
  return PARTS_CONFIG.find(config => config.className === className);
}

import { House } from '../../core/models/House';
import { Furniture } from '../../core/models/Furniture';
import { FurnitureView } from './FurnitureView';
import { IHasDepthCalculator } from '../common/abstract/IHasDepthCalculator';
import { Point } from '../../core/types/Point';

export interface FurniturePlacementOptions {
  checkCollisions?: boolean;
  snapToGrid?: boolean;
  gridSize?: number;
}

export interface FurnitureMoveResult {
  success: boolean;
  collision?: boolean;
  snappedPosition?: Point;
  message?: string;
}

export class FurnitureController {
  private draggedFurniture: FurnitureView | null = null;
  private dragOffset: Point = { x: 0, y: 0 };
  private initialPosition: Point = { x: 0, y: 0 };

  constructor(
    private readonly house: House,
    private readonly depthCalculator: IHasDepthCalculator
  ) {}

  /**
   * Start dragging a furniture piece
   */
  startDrag(furnitureView: FurnitureView, pointerX: number, pointerY: number): void {
    this.draggedFurniture = furnitureView;
    this.dragOffset = {
      x: pointerX - furnitureView.model.x,
      y: pointerY - furnitureView.model.y
    };
    this.initialPosition = {
      x: furnitureView.model.x,
      y: furnitureView.model.y
    };

    // Visual feedback
    furnitureView.alpha = 0.8;
    furnitureView.sprite.cursor = 'grabbing';
  }

  /**
   * Update drag position
   */
  updateDrag(pointerX: number, pointerY: number, options: FurniturePlacementOptions = {}): FurnitureMoveResult {
    if (!this.draggedFurniture) {
      return { success: false, message: 'No furniture being dragged' };
    }

    let targetX = pointerX - this.dragOffset.x;
    let targetY = pointerY - this.dragOffset.y;

    // Apply grid snapping if enabled
    if (options.snapToGrid) {
      const gridSize = options.gridSize || 20;
      targetX = Math.round(targetX / gridSize) * gridSize;
      targetY = Math.round(targetY / gridSize) * gridSize;
    }

    // Temporarily move furniture to check collision
    const originalX = this.draggedFurniture.model.x;
    const originalY = this.draggedFurniture.model.y;

    this.draggedFurniture.model.setPosition(targetX, targetY);

    let hasCollision = false;
    if (options.checkCollisions !== false) {
      hasCollision = this.depthCalculator.checkCollision(this.draggedFurniture);
    }

    // Visual feedback based on collision
    this.draggedFurniture.alpha = hasCollision ? 0.5 : 0.8;
    this.draggedFurniture.sprite.cursor = hasCollision ? 'not-allowed' : 'grabbing';

    return {
      success: true,
      collision: hasCollision,
      snappedPosition: options.snapToGrid ? { x: targetX, y: targetY } : undefined
    };
  }

  /**
   * End drag operation
   */
  endDrag(cancel: boolean = false): FurnitureMoveResult {
    if (!this.draggedFurniture) {
      return { success: false, message: 'No furniture being dragged' };
    }

    const hasCollision = this.depthCalculator.checkCollision(this.draggedFurniture);

    if (cancel || hasCollision) {
      // Revert to initial position
      this.draggedFurniture.model.setPosition(
        this.initialPosition.x,
        this.initialPosition.y
      );
    }

    // Reset visual state
    this.draggedFurniture.alpha = 1;
    this.draggedFurniture.sprite.cursor = 'grab';

    const result: FurnitureMoveResult = {
      success: !cancel && !hasCollision,
      collision: hasCollision,
      message: cancel ? 'Drag cancelled' : hasCollision ? 'Cannot place due to collision' : 'Furniture placed successfully'
    };

    this.draggedFurniture = null;
    return result;
  }

  /**
   * Déplace un meuble aux coordonnées (x, y).
   */
  moveFurniture(furniture: Furniture, x: number, y: number, options: FurniturePlacementOptions = {}): FurnitureMoveResult {
    let targetX = x;
    let targetY = y;

    // Apply grid snapping if enabled
    if (options.snapToGrid) {
      const gridSize = options.gridSize || 20;
      targetX = Math.round(targetX / gridSize) * gridSize;
      targetY = Math.round(targetY / gridSize) * gridSize;
    }

    // Check collision if enabled
    if (options.checkCollisions !== false) {
      const originalX = furniture.x;
      const originalY = furniture.y;

      furniture.setPosition(targetX, targetY);

      // Need to find the FurnitureView for collision check
      // This would require a view lookup mechanism
      // For now, just move the furniture

      return {
        success: true,
        snappedPosition: options.snapToGrid ? { x: targetX, y: targetY } : undefined
      };
    }

    furniture.setPosition(targetX, targetY);
    return {
      success: true,
      snappedPosition: options.snapToGrid ? { x: targetX, y: targetY } : undefined
    };
  }

  /**
   * Change l'orientation d'un meuble.
   */
  rotateFurniture(furniture: Furniture, orientation: number): FurnitureMoveResult {
    const validOrientations = [1, 2, 3, 4]; // Based on frameKeys length
    const targetOrientation = validOrientations.includes(orientation) ? orientation : 1;

    furniture.setOrientation(targetOrientation);

    return {
      success: true,
      message: `Furniture rotated to orientation ${targetOrientation}`
    };
  }

  /**
   * Supprime un meuble de la maison.
   */
  removeFurniture(furniture: Furniture): FurnitureMoveResult {
    try {
      this.house.removeFurniture(furniture);
      return {
        success: true,
        message: 'Furniture removed successfully'
      };
    } catch (error) {
      return {
        success: false,
        message: `Failed to remove furniture: ${error}`
      };
    }
  }

  /**
   * Add new furniture to the house
   */
  addFurniture(furniture: Furniture, options: FurniturePlacementOptions = {}): FurnitureMoveResult {
    // Apply grid snapping if enabled
    if (options.snapToGrid) {
      const gridSize = options.gridSize || 20;
      const snappedX = Math.round(furniture.x / gridSize) * gridSize;
      const snappedY = Math.round(furniture.y / gridSize) * gridSize;
      furniture.setPosition(snappedX, snappedY);
    }

    try {
      this.house.addFurniture(furniture);
      return {
        success: true,
        message: 'Furniture added successfully',
        snappedPosition: options.snapToGrid ? { x: furniture.x, y: furniture.y } : undefined
      };
    } catch (error) {
      return {
        success: false,
        message: `Failed to add furniture: ${error}`
      };
    }
  }

  /**
   * Get the currently dragged furniture
   */
  getDraggedFurniture(): FurnitureView | null {
    return this.draggedFurniture;
  }

  /**
   * Cancel any ongoing drag operation
   */
  cancelDrag(): void {
    if (this.draggedFurniture) {
      this.endDrag(true);
    }
  }

{ FurnitureController } from './FurnitureController';
import * as ZOrder from '../common/ZOrder';

export class FurnitureView extends Container implements Drawable, IHasDepth {
  public readonly sprite: Sprite;
  private _points: Point[] = [];
  private controller: FurnitureController;

  constructor(
    public readonly model: Furniture,
    public readonly depthCalculator: IHasDepthCalculator,
    controller?: FurnitureController
  ) {
    super();
    this.sprite = new PrecisionSprite(Texture.EMPTY);
    this.sprite.eventMode = 'dynamic';
    this.sprite.cursor = 'grab';
    this.addChild(this.sprite);

    // Create controller if not provided (backwards compatibility)
    this.controller = controller || new FurnitureController(
      { addFurniture: () => {}, removeFurniture: () => {} } as any, // Mock house
      depthCalculator

this.sprite.on('rightclick', this.onRightClick);
}

private readonly onPointerDown = (evt: FederatedPointerEvent): void => {
  if (this.model.base.type !== 18) return; // Only allow dragging furniture, not floors

  this.controller.startDrag(this, evt.globalX, evt.globalY);

  // Listen for global pointer events
  const onPointerMove = (evt: FederatedPointerEvent) => {
    this.controller.updateDrag(evt.globalX, evt.globalY, {
      checkCollisions: true,
      snapToGrid: evt.shiftKey, // Hold shift to snap to grid
      gridSize: 20
    });
  };

  const onPointerUp = () => {
    this.controller.endDrag();
    // Clean up global listeners
    this.sprite.off('globalpointermove', onPointerMove);
    this.sprite.off('globalpointerup', onPointerUp);
    this.sprite.off('globalpointerupoutside', onPointerUp);
  };

  // Add global listeners for drag continuation
  this.sprite.on('globalpointermove', onPointerMove);
  this.sprite.on('globalpointerup', onPointerUp);
  this.sprite.on('globalpointerupoutside', onPointerUp);

  evt.stopPropagation();
};

private readonly onPointerUp = (evt: FederatedPointerEvent): void => {
  // Handled by global listeners in onPointerDown
};

private readonly onRightClick = (evt: FederatedPointerEvent): void => {
  if (this.model.base.type !== 18) return;

  // Rotate furniture on right click
  const currentOrientation = this.model.orientation;
  const newOrientation = (currentOrientation % 4) + 1;
  this.controller.rotateFurniture(this.model, newOrientation);

  evt.stopPropagation();
};

